class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        MOD = 1000000007
        prev = [0] * (target + 1)
        prev[0] = 1
        for _ in range(n):
            cur = [0] * (target + 1)
            window = 0
            for s in range(1, target + 1):
                window = (window + prev[s - 1]) % MOD
                if s - k - 1 >= 0:
                    window = (window - prev[s - k - 1]) % MOD
                cur[s] = window
            prev = cur
        return prev[target] % MOD

